suppressPackageStartupMessages({library(data.table);library(ggplot2)})
BASE='almanac_conditionals/state_conditioned_bridge/program_first'
# Rank is a model-size diagnostic curve, not a correlation scatterplot.
rk=fread(file.path(BASE,'results/rank_screening.tsv'));chosen=rk[chosen==TRUE,rank]
metrics=c('relative_reconstruction_error','q10_stability','negative_silhouette_fraction','minimum_source_coherence')
labels=c('Reconstruction error (lower is better)','Repeat stability: 10th percentile','Fraction of genes with negative silhouette','Weakest within-program source coherence')
r=melt(rk,id.vars=c('rank','chosen'),measure.vars=metrics,variable.name='metric');r[,metric:=factor(metric,levels=metrics,labels=labels)]
gates=data.table(metric=factor(labels[-1],levels=labels),threshold=c(.5,.2,.05))
pr=ggplot(r,aes(rank,value))+geom_vline(xintercept=chosen,color='#B44745',linetype=3,linewidth=.5)+geom_hline(data=gates,aes(yintercept=threshold),color='grey55',linetype=2,linewidth=.4)+geom_line(linewidth=.5,color='#426A89')+geom_point(aes(fill=chosen),shape=21,size=2.6,color='#426A89')+scale_fill_manual(values=c('FALSE'='white','TRUE'='#B44745'),guide='none')+scale_x_continuous(breaks=c(10,20,40,80))+facet_wrap(~metric,ncol=2,scales='free_y')+labs(x='Number of programs',y=NULL,title=sprintf('Sensitivity-blind rank comparison: %d programs selected',chosen),subtitle='Three deterministic screening repeats; chosen rank then fitted with ten repeats',caption='Red dotted line: chosen rank. Gray dashed lines: diagnostic thresholds.\nRank uses reconstruction elbow among stable, nonempty solutions; silhouette and source gates are reported separately.\nReconstruction measures the soft consensus span of the discovery matrix; HGF capture is audited separately.')+theme_classic(base_size=9)+theme(strip.background=element_blank(),strip.text=element_text(size=8,face='bold'),plot.title=element_text(size=11,face='bold'),plot.subtitle=element_text(size=8),plot.caption=element_text(size=7),panel.spacing=grid::unit(5,'mm'))
ggsave(file.path(BASE,'figures/rank_diagnostics.pdf'),pr,width=7.8,height=5.2);ggsave(file.path(BASE,'figures/rank_diagnostics.png'),pr,width=7.8,height=5.2,dpi=170)
